/// <summary>
/// Extension class of form data source METSalesLine in form SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, METSalesLine))]
public final class METSalesTableFormMETSalesLineDS_Extension
{
}

Method.Source:
/// <summary>
/// Write the record
/// </summary>
public void write()
{
    // Skip the write operation of formDataSourceStr(SalesTable, METSalesLine).
    // The wirte operation is handled in the formDataSourceStr(SalesTable, SalesLine) and SalesLine_OnWritten event.
    // This change is for Dual Write scenario where the METSalesLine record and the SalesLine record needs be written in one TTs.
    return;       
}

    /// <summary>
    /// Validate the record
    /// </summary>
    /// <returns>Result of the validation</returns>
    public boolean validatewrite()
    {
        boolean ret = true;
        METSalesLine metSalesLine = this.cursor();

        if (METSalesLine.SalesLine)
        {
            next validatewrite();
        }

        return ret;
    }

    /// <summary>
    /// active method on datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();
        
        this.object(fieldNum(METSalesLine, ApplyBonus)).allowEdit(false);
        this.object(fieldNum(METSalesLine, TurnInLineType)).allowEdit(false);
        this.object(fieldNum(METSalesLine, SupplierReference)).allowEdit(false);
        this.object(fieldNum(METSalesLine, TransmissionNumber)).allowEdit(false);
        this.object(fieldNum(METSalesLine, DiscountValue)).allowEdit(false);
        this.object(fieldNum(METSalesLine, VendorDealAmount)).allowEdit(false);
        this.object(fieldNum(METSalesLine, NoClaimBonus)).allowEdit(false);

        //Bug 188150-Update Editable / Non-Editable fields- start
        this.object(fieldNum(METSalesLine, SalesUnitCase)).allowEdit(false);
        this.object(fieldNum(METSalesLine, SalesUnitVolume)).allowEdit(false);
        this.object(fieldNum(METSalesLine, SalesUnitWeight)).allowEdit(false);
        this.object(fieldNum(METSalesLine, ActualUnitVolume)).allowEdit(false);
        this.object(fieldNum(METSalesLine, ActualUnitWeight)).allowEdit(false);
        //Bug 188150-Update Editable / Non-Editable fields- end
        
        return ret;
    }
